# cook your dish here
import sys

input = sys.stdin.readline

n = int(input())

for _ in range(n):
    n = int(input())
    a = list(map(int,input().split()))
    
    a.sort(reverse=True)
    
    pref = [0] * (3* n +1)
    
    for i in range(3 * n ):
        pref[i + 1] = pref[i] +a[i]
        
    def value(A,B):
        
        k = A + 2 * B
        end = 3 *n-2*A-B
        
        return(
            6 * pref[A]
            + 4 * (pref[k] - pref[A])
            + 3 * (pref[end] - pref[k])
            
            )
            
    ans = 0 
    
    for A in range(n+1):
        
        low = 0
        high = n-A
        
        
        while low < high :
            mid = (low + high) //2
            
            k = A + 2 * mid
            end = 3 * n - 2 * A - mid
            
            delta = a[k] + a[k+1] - 3 *a[end-1]
            
            if delta >= 0:
                low = mid+1
            else:
                high = mid
                
        for B in {low, max(0, low - 1)}:
            if B <= n-A:
                ans = max(ans,value(A,B))
                
    print(ans)
